{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Salicylic acid, a small aromatic acid with high assay-transfer relevance, showed absolute bioavailability of 0.97 after oral administration, supporting high oral bioavailability for the acidic coumarin-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Phenylbutyrate, a lipophilic aromatic carboxylic acid, had an absolute oral bioavailability of 78% in humans, supporting high F for the lipophilic acidic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Bufuralol, a lipophilic aromatic drug, showed systemic availability of 0.83 after oral dosing, well above the 20% threshold and supportive of high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Diphenhydramine, a lipophilic aromatic drug, had systemic availability of 0.69 after oral administration, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Vorinostat, an aromatic hydroxamic acid with high transfer relevance, showed mean oral bioavailability of about 50%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Meperidine, an aromatic ester/amine, had an experimentally determined oral bioavailability of 0.52, supporting F above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Ampicillin, a polar carboxylic acid-containing drug, had mean oral bioavailability of 0.41 in young subjects, still supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Tapentadol, a phenolic drug with extensive first-pass metabolism, had absolute oral bioavailability of approximately 32%, supporting high F at the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Labetalol, despite first-pass metabolism, had a mean oral bioavailability of 33% in normal subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "One labetalol record reported 18% bioavailability, below the threshold, but this is an outlier within the same molecule whose other records average about 30%, so it does not outweigh the consistent supportive evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a lipophilic 4-hydroxycoumarin anticoagulant (phenprocoumon-like). All high-transfer experimental analogues with measured oral bioavailability are at or above the 20% threshold, with many in the 30-80% range and salicylic acid near-complete. The single subthreshold labetalol record is an outlier and not sufficient to predict low. Overall evidence strongly supports high oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct phenprocoumon bioavailability measurement is present in the supplied evidence; prediction relies on high-transfer analogues.",
    "Several analogues have F only modestly above 20%, so the margin above threshold is not uniformly large.",
    "The single contradictory labetalol record (18%) is from the same molecule as multiple supportive records and is treated as an outlier."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

